1	import * as THREE from "three";
2	import { SceneObject } from "../../core/SceneObject.js";
3	import { Helpers } from "../../utils/Helpers.js";
4	import type {
5	  TransitionVeilTweenProps,
6	} from "../../types/object.types.js";
7	import type { TransitionVeilObjectOptions } from "../../types/object-visual.types.js";
8	import type {
9	  ShaderUniformRecord,
10	  TransitionVeilRuntimePort,
11	  TransitionVeilRuntimeState,
12	} from "../../types/object-runtime.types.js";
13	import transitionVeilVertexShader from "../../../shaders/who-reveal/vertex.glsl?raw";
14	import transitionVeilFragmentShader from "../../../shaders/who-reveal/fragment.glsl?raw";
15	
16	const TRANSITION_VEIL_RENDER_ORDER = 2200;
17	const TRANSITION_VEIL_DEFAULT_OPACITY = 0.96;
18	const TRANSITION_VEIL_DEFAULT_NOISE_STRENGTH = 1;
19	const TRANSITION_VEIL_DEFAULT_REVEAL_SOFTNESS = 0.24;
20	const TRANSITION_VEIL_DEFAULT_SIZE_X = 2.4;
21	const TRANSITION_VEIL_DEFAULT_SIZE_Y = 1.8;
22	const TRANSITION_VEIL_DEFAULT_COLOR_DARK = 0xc7d3de;
23	const TRANSITION_VEIL_DEFAULT_COLOR_LIGHT = 0xfbfdff;
24	const TRANSITION_VEIL_TIME_EPSILON = 0.0001;
25	const TRANSITION_VEIL_PROGRESS_EPSILON = 0.0001;
26	const TRANSITION_VEIL_DEFAULT_DISTANCE = 16;
27	const TRANSITION_VEIL_COVER_OVERSCAN = 1.35;
28	const TRANSITION_VEIL_CAMERA_FORWARD = new THREE.Vector3();
29	const TRANSITION_VEIL_CAMERA_RIGHT = new THREE.Vector3();
30	const TRANSITION_VEIL_CAMERA_UP = new THREE.Vector3();
31	const TRANSITION_VEIL_OFFSET = new THREE.Vector3();
32	
33	export class TransitionVeil
34	  extends SceneObject<TransitionVeilTweenProps>
35	  implements TransitionVeilRuntimePort
36	{
37	  private _options: Partial<TransitionVeilObjectOptions> = {};
38	  private _runtimeState: TransitionVeilRuntimeState = { active: false, progress: 0 };
39	  private _mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial> | null =
40	    null;
41	  private _material: THREE.ShaderMaterial | null = null;
42	  private _noiseTexture: THREE.Texture | null = null;
43	  private _perlinTexture: THREE.Texture | null = null;
44	  private _elapsedTime = 0;
45	  private _lastActive = false;
46	  private _lastProgress = Number.NaN;
47	  private _lastResolutionWidth = 0;
48	  private _lastResolutionHeight = 0;
49	  private _lastTimeUniform = Number.NaN;
50	
51	  setOptions(props: Partial<TransitionVeilObjectOptions> | undefined): this {
52	    if (!props) return this;
53	    this._options = {
54	      ...this._options,
55	      ...props,
56	      position: { ...this._options.position, ...props.position },
57	      rotation: { ...this._options.rotation, ...props.rotation },
58	      scale: { ...this._options.scale, ...props.scale },
59	      plane: { ...this._options.plane, ...props.plane },
60	      shader: {
61	        ...this._options.shader,
62	        ...props.shader,
63	        textures: {
64	          ...this._options.shader?.textures,
65	          ...props.shader?.textures,
66	        },
67	        size: {
68	          ...this._options.shader?.size,
69	          ...props.shader?.size,
70	        },
71	      },
72	    };
73	    return this;
74	  }
75	
76	  setRuntimeState(state: Partial<TransitionVeilRuntimeState>): void {
77	    const prevActive = this._runtimeState.active;
78	    const prevProgress = this._runtimeState.progress;
79	    this._runtimeState = {
80	      ...this._runtimeState,
81	      ...state,
82	    };
83	    const nextActive = this._runtimeState.active;
84	    const nextProgress = this._runtimeState.progress ?? 0;
85	    if (prevActive !== nextActive) {
86	      console.log(`[VEIL:mesh] active changed  ${String(prevActive)} → ${String(nextActive)}  progress=${nextProgress.toFixed(4)}`);
87	    } else if (
88	      Math.abs((prevProgress ?? 0) - nextProgress) > 0.05
89	    ) {
90	      console.log(`[VEIL:mesh] progress jump  ${(prevProgress ?? 0).toFixed(4)} → ${nextProgress.toFixed(4)}  active=${String(nextActive)}`);
91	    }
92	    this._syncVisibility();
93	    if (!this._runtimeState.active) return;
94	    this._applyRuntimeUniforms();
95	  }
96	
97	  getRuntimeState(): TransitionVeilRuntimeState {
98	    return { ...this._runtimeState };
99	  }
100	
101	  override getAnimationTarget(): THREE.Object3D | null {
102	    return this.getTimelineRoot();
103	  }
104	
105	  override getBloomEnabled(): boolean {
106	    return false;
107	  }
108	
109	  override getTweenApplyMode(): "mergeAndSync" {
110	    return "mergeAndSync";
111	  }
112	
113	  protected override getOptions(): Record<string, unknown> {
114	    return this._options;
115	  }
116	
117	  protected override mergeOptionsFromTimeline(
118	    vars: Partial<TransitionVeilTweenProps>,
119	  ): void {
120	    if (vars.position) this._options.position = { ...this._options.position, ...vars.position };
121	    if (vars.rotation) this._options.rotation = { ...this._options.rotation, ...vars.rotation };
122	    if (vars.scale) this._options.scale = { ...this._options.scale, ...vars.scale };
123	    if (typeof vars.visible === "boolean") this._options.visible = vars.visible;
124	    if (typeof vars.progress === "number") this._runtimeState.progress = vars.progress;
125	    if (typeof vars.active === "boolean") this._runtimeState.active = vars.active;
126	  }
127	
128	  protected override applyVisibility(visible: boolean): void {
129	    const root = this.getTimelineRoot();
130	    if (!root) return;
131	    root.visible = visible && (this._runtimeState.active ?? false);
132	  }
133	
134	  protected override syncFromOptions(): void {
135	    this._applyStaticUniforms();
136	    this._syncVisibility();
137	  }
138	
139	  override async runObject(): Promise<void> {
140	    const scene = this._context?.scene;
141	    if (!scene) return;
142	
143	    const root = this.ensureTimelineRoot("transitionVeilRoot");
144	    if (!root) return;
145	    await this._loadTextures();
146	
147	    this._material = this._createMaterial();
148	    this._mesh = new THREE.Mesh(this._createGeometry(), this._material);
149	    this._mesh.frustumCulled = false;
150	    this._mesh.renderOrder = TRANSITION_VEIL_RENDER_ORDER;
151	    root.add(this._mesh);
152	
153	    this._followCamera();
154	    this._applyStaticUniforms();
155	    this._applyRuntimeUniforms();
156	    this._syncVisibility();
157	  }
158	
159	  override runUpdate(deltaTime: number): void {
160	    if (this._disposed) return;
161	    this._followCamera();
162	    if (!this._runtimeState.active) return;
163	    this._elapsedTime += Number.isFinite(deltaTime) ? Math.max(0, deltaTime) : 0;
164	    this._applyRuntimeUniforms();
165	  }
166	
167	  override dispose(): void {
168	    this._mesh?.geometry.dispose();
169	    this._material?.dispose();
170	    this._noiseTexture?.dispose();
171	    this._perlinTexture?.dispose();
172	    this._mesh = null;
173	    this._material = null;
174	    this._noiseTexture = null;
175	    this._perlinTexture = null;
176	    super.dispose();
177	  }
178	
179	  private async _loadTextures(): Promise<void> {
180	    const loadTexture = this._context?.loadTexture;
181	    const textures = this._options.shader?.textures;
182	    const perlinTextureUrl = textures?.perlinTextureUrl?.trim();
183	    const noiseTextureUrl = textures?.noiseTextureUrl?.trim();
184	    if (!loadTexture || !perlinTextureUrl || !noiseTextureUrl) return;
185	
186	    const [perlinTexture, noiseTexture] = await Promise.all([
187	      loadTexture(this.resolveAssetPath(perlinTextureUrl)),
188	      loadTexture(this.resolveAssetPath(noiseTextureUrl)),
189	    ]);
190	    this._prepareTexture(perlinTexture);
191	    this._prepareTexture(noiseTexture);
192	    this._perlinTexture = perlinTexture;
193	    this._noiseTexture = noiseTexture;
194	    this._context?.prepareTexture?.(perlinTexture);
195	    this._context?.prepareTexture?.(noiseTexture);
196	  }
197	
198	  private _prepareTexture(texture: THREE.Texture): void {
199	    texture.wrapS = THREE.RepeatWrapping;
200	    texture.wrapT = THREE.RepeatWrapping;
201	    texture.magFilter = THREE.LinearFilter;
202	    texture.minFilter = THREE.LinearMipmapLinearFilter;
203	    texture.needsUpdate = true;
204	  }
205	
206	  private _createGeometry(): THREE.PlaneGeometry {
207	    return new THREE.PlaneGeometry(1, 1, 1, 1);
208	  }
209	
210	  private _createMaterial(): THREE.ShaderMaterial {
211	    return new THREE.ShaderMaterial({
212	      uniforms: {
213	        uTime: { value: 0 },
214	        uProgress: { value: 0 },
215	        uOpacity: {
216	          value: this._finiteOr(
217	            this._options.shader?.opacity,
218	            TRANSITION_VEIL_DEFAULT_OPACITY,
219	          ),
220	        },
221	        uNoiseStrength: {
222	          value: this._finiteOr(
223	            this._options.shader?.noiseStrength,
224	            TRANSITION_VEIL_DEFAULT_NOISE_STRENGTH,
225	          ),
226	        },
227	        uRevealSoftness: {
228	          value: this._finiteOr(
229	            this._options.shader?.revealSoftness,
230	            TRANSITION_VEIL_DEFAULT_REVEAL_SOFTNESS,
231	          ),
232	        },
233	        uResolution: { value: new THREE.Vector2(1, 1) },
234	        uSize: {
235	          value: new THREE.Vector2(
236	            this._finiteOr(
237	              this._options.shader?.size?.x,
238	              TRANSITION_VEIL_DEFAULT_SIZE_X,
239	            ),
240	            this._finiteOr(
241	              this._options.shader?.size?.y,
242	              TRANSITION_VEIL_DEFAULT_SIZE_Y,
243	            ),
244	          ),
245	        },
246	        uDarkColor: {
247	          value: new THREE.Color(TRANSITION_VEIL_DEFAULT_COLOR_DARK),
248	        },
249	        uLightColor: {
250	          value: new THREE.Color(TRANSITION_VEIL_DEFAULT_COLOR_LIGHT),
251	        },
252	        tPerlin: { value: this._perlinTexture },
253	        tNoise: { value: this._noiseTexture },
254	      },
255	      vertexShader: transitionVeilVertexShader,
256	      fragmentShader: transitionVeilFragmentShader,
257	      transparent: true,
258	      depthWrite: false,
259	      depthTest: false,
260	      side: THREE.DoubleSide,
261	    });
262	  }
263	
264	  private _applyStaticUniforms(): void {
265	    const uniforms = this._material?.uniforms as ShaderUniformRecord | undefined;
266	    if (!uniforms) return;
267	    this._followCamera();
268	    this._setUniformNumber(
269	      uniforms,
270	      "uOpacity",
271	      this._finiteOr(
272	        this._options.shader?.opacity,
273	        TRANSITION_VEIL_DEFAULT_OPACITY,
274	      ),
275	    );
276	    this._setUniformNumber(
277	      uniforms,
278	      "uNoiseStrength",
279	      this._finiteOr(
280	        this._options.shader?.noiseStrength,
281	        TRANSITION_VEIL_DEFAULT_NOISE_STRENGTH,
282	      ),
283	    );
284	    this._setUniformNumber(
285	      uniforms,
286	      "uRevealSoftness",
287	      this._finiteOr(
288	        this._options.shader?.revealSoftness,
289	        TRANSITION_VEIL_DEFAULT_REVEAL_SOFTNESS,
290	      ),
291	    );
292	    const size = uniforms.uSize?.value;
293	    if (!(size instanceof THREE.Vector2)) return;
294	    size.set(
295	      this._finiteOr(
296	        this._options.shader?.size?.x,
297	        TRANSITION_VEIL_DEFAULT_SIZE_X,
298	      ),
299	      this._finiteOr(
300	        this._options.shader?.size?.y,
301	        TRANSITION_VEIL_DEFAULT_SIZE_Y,
302	      ),
303	    );
304	  }
305	
306	  private _applyRuntimeUniforms(): void {
307	    const uniforms = this._material?.uniforms as ShaderUniformRecord | undefined;
308	    if (!uniforms) return;
309	    const isActive = this._runtimeState.active ?? false;
310	    const progress = Helpers.clamp01(
311	      this._runtimeState.progress ?? this._options.progress ?? 0,
312	    );
313	    if (
314	      isActive ||
315	      this._lastActive !== isActive ||
316	      Math.abs(progress - this._lastProgress) > TRANSITION_VEIL_PROGRESS_EPSILON
317	    ) {
318	      this._setUniformNumber(uniforms, "uProgress", progress);
319	      this._lastProgress = progress;
320	    }
321	    if (
322	      isActive &&
323	      Math.abs(this._elapsedTime - this._lastTimeUniform) > TRANSITION_VEIL_TIME_EPSILON
324	    ) {
325	      this._setUniformNumber(uniforms, "uTime", this._elapsedTime);
326	      this._lastTimeUniform = this._elapsedTime;
327	    }
328	    const resolution = uniforms.uResolution?.value;
329	    const renderer = this._context?.renderer;
330	    const width = renderer?.domElement?.width;
331	    const height = renderer?.domElement?.height;
332	    if (!(resolution instanceof THREE.Vector2)) return;
333	    if (!Number.isFinite(width) || !Number.isFinite(height)) return;
334	    const nextWidth = width as number;
335	    const nextHeight = height as number;
336	    if (
337	      nextWidth !== this._lastResolutionWidth ||
338	      nextHeight !== this._lastResolutionHeight
339	    ) {
340	      resolution.set(nextWidth, nextHeight);
341	      this._lastResolutionWidth = nextWidth;
342	      this._lastResolutionHeight = nextHeight;
343	    }
344	    this._lastActive = isActive;
345	  }
346	
347	  private _syncVisibility(): void {
348	    const root = this.getTimelineRoot();
349	    if (!root) return;
350	    root.visible = this._options.visible !== false && (this._runtimeState.active ?? false);
351	  }
352	
353	  private _followCamera(): void {
354	    const root = this.getTimelineRoot();
355	    const camera = this._context?.camera;
356	    if (!root || !camera) return;
357	
358	    const distance = this._resolveDistance();
359	    camera.getWorldDirection(TRANSITION_VEIL_CAMERA_FORWARD);
360	    root.quaternion.copy(camera.quaternion);
361	    root.position.copy(camera.position).addScaledVector(
362	      TRANSITION_VEIL_CAMERA_FORWARD,
363	      distance,
364	    );
365	
366	    TRANSITION_VEIL_CAMERA_RIGHT.set(1, 0, 0).applyQuaternion(camera.quaternion);
367	    TRANSITION_VEIL_CAMERA_UP.set(0, 1, 0).applyQuaternion(camera.quaternion);
368	    TRANSITION_VEIL_OFFSET.set(
369	      this._finiteOr(this._options.position?.x, 0),
370	      this._finiteOr(this._options.position?.y, 0),
371	      this._finiteOr(this._options.position?.z, 0),
372	    );
373	    root.position
374	      .addScaledVector(TRANSITION_VEIL_CAMERA_RIGHT, TRANSITION_VEIL_OFFSET.x)
375	      .addScaledVector(TRANSITION_VEIL_CAMERA_UP, TRANSITION_VEIL_OFFSET.y)
376	      .addScaledVector(TRANSITION_VEIL_CAMERA_FORWARD, TRANSITION_VEIL_OFFSET.z);
377	
378	    const coverSize = this._resolveCoverSize(camera, distance);
379	    const planeWidth = this._finiteOr(this._options.plane?.width, coverSize.width);
380	    const planeHeight = this._finiteOr(this._options.plane?.height, coverSize.height);
381	    root.scale.set(
382	      Math.max(planeWidth, coverSize.width),
383	      Math.max(planeHeight, coverSize.height),
384	      1,
385	    );
386	  }
387	
388	  private _resolveDistance(): number {
389	    return this._finiteOr(
390	      this._options.plane?.distance,
391	      TRANSITION_VEIL_DEFAULT_DISTANCE,
392	    );
393	  }
394	
395	  private _resolveCoverSize(
396	    camera: THREE.Camera,
397	    distance: number,
398	  ): { width: number; height: number } {
399	    if (camera instanceof THREE.PerspectiveCamera) {
400	      const verticalFov = THREE.MathUtils.degToRad(camera.fov);
401	      const height =
402	        2 * Math.tan(verticalFov * 0.5) * distance * TRANSITION_VEIL_COVER_OVERSCAN;
403	      return {
404	        width: height * camera.aspect,
405	        height,
406	      };
407	    }
408	    if (camera instanceof THREE.OrthographicCamera) {
409	      const width =
410	        ((camera.right - camera.left) / Math.max(camera.zoom, 0.0001)) *
411	        TRANSITION_VEIL_COVER_OVERSCAN;
412	      const height =
413	        ((camera.top - camera.bottom) / Math.max(camera.zoom, 0.0001)) *
414	        TRANSITION_VEIL_COVER_OVERSCAN;
415	      return { width, height };
416	    }
417	    return {
418	      width: this._finiteOr(this._options.plane?.width, 1) * TRANSITION_VEIL_COVER_OVERSCAN,
419	      height: this._finiteOr(this._options.plane?.height, 1) * TRANSITION_VEIL_COVER_OVERSCAN,
420	    };
421	  }
422	
423	  private _setUniformNumber(
424	    uniforms: ShaderUniformRecord,
425	    key: string,
426	    value: number,
427	  ): void {
428	    const target = uniforms[key];
429	    if (!target) return;
430	    target.value = value;
431	  }
432	
433	  private _finiteOr(value: number | undefined, fallback: number): number {
434	    return Number.isFinite(value) ? (value as number) : fallback;
435	  }
436	}
