1	import type { GsapGlobal } from "../types/gsap.types.js";
2	import { Helpers } from "../utils/Helpers.js";
3	import type {
4	  SceneTransitionPlayOptions,
5	  SceneTransitionStep,
6	} from "../types/runtime.types.js";
7	import type {
8	  TransitionEaseKey,
9	  TransitionVeilRuntimePort,
10	} from "../types/object-runtime.types.js";
11	
12	const DEFAULT_INACTIVE_PROGRESS = 1;
13	
14	export class SceneTransitionRuntime {
15	  syncVeil(veil: TransitionVeilRuntimePort | null, progress: number): void {
16	    if (!veil) return;
17	    veil.setRuntimeState({
18	      active: true,
19	      progress: Helpers.clamp01(progress),
20	    });
21	  }
22	
23	  resetVeil(
24	    veil: TransitionVeilRuntimePort | null,
25	    inactiveProgress = DEFAULT_INACTIVE_PROGRESS,
26	  ): void {
27	    if (!veil) return;
28	    veil.setRuntimeState({
29	      active: false,
30	      progress: Helpers.clamp01(inactiveProgress),
31	    });
32	  }
33	
34	  async play(
35	    options: SceneTransitionPlayOptions,
36	    gsap: GsapGlobal | null,
37	  ): Promise<void> {
38	    const { veil, steps, onStepComplete, initialState, finalState } = options;
39	    console.group("[VEIL:play] transition start");
40	    console.log("steps:", steps.map((s, i) => `[${i}] ${s.from}→${s.to} ${s.duration}s`));
41	    console.log("initialState:", initialState, "finalState:", finalState);
42	
43	    if (!veil || steps.length === 0) {
44	      console.warn("[VEIL:play] no veil or no steps — skipping");
45	      console.groupEnd();
46	      if (onStepComplete) await onStepComplete(0);
47	      return;
48	    }
49	
50	    veil.setRuntimeState({
51	      active: true,
52	      progress: Helpers.clamp01(initialState?.progress ?? steps[0]?.from ?? 0),
53	      ...initialState,
54	    });
55	
56	    if (!gsap) {
57	      for (let index = 0; index < steps.length; index += 1) {
58	        veil.setRuntimeState({
59	          active: true,
60	          progress: Helpers.clamp01(steps[index].to),
61	        });
62	        if (onStepComplete) await onStepComplete(index);
63	      }
64	      veil.setRuntimeState({
65	        active: false,
66	        progress: Helpers.clamp01(
67	          finalState?.progress ?? steps[steps.length - 1]?.to ?? 1,
68	        ),
69	        ...finalState,
70	      });
71	      console.groupEnd();
72	      return;
73	    }
74	
75	    for (let index = 0; index < steps.length; index += 1) {
76	      await this._playStep(gsap, veil, steps[index], index);
77	      if (onStepComplete) await onStepComplete(index);
78	    }
79	
80	    veil.setRuntimeState({
81	      active: false,
82	      progress: Helpers.clamp01(
83	        finalState?.progress ?? steps[steps.length - 1]?.to ?? 1,
84	      ),
85	      ...finalState,
86	    });
87	    console.log("[VEIL:play] transition complete — finalState applied");
88	    console.groupEnd();
89	  }
90	
91	  private async _playStep(
92	    gsap: GsapGlobal,
93	    veil: TransitionVeilRuntimePort,
94	    step: SceneTransitionStep,
95	    stepIndex = 0,
96	  ): Promise<void> {
97	    const stepLabel = stepIndex === 0 ? "cover" : stepIndex === 1 ? "hold" : "reveal";
98	    const t0 = performance.now();
99	    console.log(`[VEIL:step] ${stepLabel} START  from=${step.from} to=${step.to} dur=${step.duration}s`);
100	
101	    const state = { progress: Helpers.clamp01(step.from) };
102	    veil.setRuntimeState({
103	      active: true,
104	      progress: state.progress,
105	    });
106	
107	    await new Promise<void>((resolve) => {
108	      gsap.to(state, {
109	        progress: Helpers.clamp01(step.to),
110	        duration: Math.max(0, step.duration),
111	        ease: this._resolveEase(step.ease),
112	        onUpdate: () => {
113	          veil.setRuntimeState({
114	            active: true,
115	            progress: state.progress,
116	          });
117	        },
118	        onComplete: () => resolve(),
119	      });
120	    });
121	
122	    console.log(`[VEIL:step] ${stepLabel} DONE   elapsed=${((performance.now() - t0) / 1000).toFixed(2)}s  finalProgress=${state.progress.toFixed(4)}`);
123	  }
124	
125	  private _resolveEase(ease: TransitionEaseKey | undefined): string {
126	    if (ease === "easeInOutCubic") return "power2.inOut";
127	    return "none";
128	  }
129	}
