198	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
199	    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
200	  ): void {
201	    policies.veils?.forEach((policy) => {
202	      this._setVeilInactive(policy, resolveTransitionVeil);
203	    });
204	  }
