206	  private _resetSceneOverlayPolicies<
207	    TSceneKey extends string,
208	    TSheetId extends string,
209	  >(
210	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
211	    root?: ParentNode | null,
212	  ): void {
213	    policies.overlays?.forEach((policy) => {
214	      this._setOverlayTargetOpacity(
215	        this._resolveDomTarget(policies, policy.targetKey, root),
216	        0,
217	      );
218	    });
219	  }
220	
221	  private _resolveOverlayOpacity<
222	    TSceneKey extends string,
223	    TSheetId extends string,
224	  >(
225	    sceneKey: TSceneKey,
226	    progress: number,
227	    sheetId: TSheetId | null,
228	    policy: SceneOverlayPolicy<TSceneKey, TSheetId>,
229	  ): number | null {
230	    for (const window of policy.windows) {
231	      const value = this._resolveTransitionWindowValue(
232	        sceneKey,
233	        progress,
234	        sheetId,
235	        window,
236	      );
237	      if (value == null) continue;
238	      return value;
239	    }
240	    return null;
241	  }
242	
243	  private _applyVisibilityPolicy<
244	    TSceneKey extends string,
245	    TSheetId extends string,
246	  >(
247	    sceneKey: TSceneKey,
248	    sheetId: TSheetId | null,
249	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
250	    policy: SceneVisibilityPolicy<TSceneKey, TSheetId>,
251	    root?: ParentNode | null,
252	  ): void {
253	    const target = this._resolveDomTarget(policies, policy.targetKey, root);
254	    if (!target) return;
255	    const isActive = policy.activeStates.some((state) =>
256	      this._isActiveSceneState(sceneKey, sheetId, state),
257	    );
258	    target.dataset[policy.datasetKey] = isActive ? "true" : "false";
259	  }
260	
261	  private _applyVeilPolicy<
262	    TSceneKey extends string,
263	    TSheetId extends string,
264	  >(
265	    sceneKey: TSceneKey,
266	    progress: number,
267	    sheetId: TSheetId | null,
268	    policy: SceneVeilPolicy<TSceneKey, TSheetId>,
269	    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
270	  ): void {
271	    const reveal = this._resolveTransitionVeil(policy.objectId, resolveTransitionVeil);
272	    if (!reveal) return;
273	
274	    for (const window of policy.windows) {
275	      const veilProgress = this._resolveTransitionWindowValue(
276	        sceneKey,
277	        progress,
278	        sheetId,
279	        window,
280	      );
281	      if (veilProgress == null) continue;
282	      this._sceneTransitionRuntime.syncVeil(reveal, veilProgress);
283	      return;
284	    }
285	
286	    this._sceneTransitionRuntime.resetVeil(
287	      reveal,
288	      policy.inactiveProgress ?? SCENE_TRANSITION_VEIL_SEQUENCE.inactiveProgress,
289	    );
290	  }
291	
292	  private _setVeilInactive<
293	    TSceneKey extends string,
294	    TSheetId extends string,
295	  >(
296	    policy: SceneVeilPolicy<TSceneKey, TSheetId>,
297	    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
298	  ): void {
299	    const reveal = this._resolveTransitionVeil(policy.objectId, resolveTransitionVeil);
300	    if (!reveal) return;
301	    this._sceneTransitionRuntime.resetVeil(
302	      reveal,
303	      policy.inactiveProgress ?? SCENE_TRANSITION_VEIL_SEQUENCE.inactiveProgress,
304	    );
305	  }
306	
307	  private _resolveTransitionVeil(
308	    objectId = sceneTransitionVeil,
309	    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
310	  ): TransitionVeilRuntimePort | null {
311	    return resolveTransitionVeil?.(objectId) ?? null;
312	  }
313	
314	  private _resolveDomTarget<
315	    TSceneKey extends string,
316	    TSheetId extends string,
317	  >(
318	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
319	    targetKey: SceneDomTargetKey,
320	    root?: ParentNode | null,
321	  ): HTMLElement | null {
322	    if (typeof document === "undefined") return null;
323	    const selector = policies.domTargets?.[targetKey];
324	    if (!selector) return null;
325	    return this._resolveCachedDomTarget(selector, root);
326	  }
327	
328	  private _resolveCachedDomTarget(
329	    selector: string,
330	    root?: ParentNode | null,
331	  ): HTMLElement | null {
332	    const cache = this._resolveDomTargetCache(root);
333	    const cached = cache.get(selector);
334	    if (cached?.isConnected) return cached;
335	    const resolved = (root ?? document).querySelector<HTMLElement>(selector);
336	    cache.set(selector, resolved ?? null);
337	    return resolved;
338	  }
339	
340	  private _resolveDomTargetCache(
341	    root?: ParentNode | null,
342	  ): Map<string, HTMLElement | null> {
343	    if (!root) return this._globalDomTargetCache;
344	    const existing = this._scopedDomTargetCache.get(root);
345	    if (existing) return existing;
346	    const next = new Map<string, HTMLElement | null>();
347	    this._scopedDomTargetCache.set(root, next);
348	    return next;
349	  }
