7	export class IntroHandoffRuntime {
8	  async transitionToHero(options: IntroHeroTransitionOptions): Promise<void> {
9	    const {
10	      gsap,
11	      transitionRuntime,
12	      veil,
13	      steps,
14	      inactiveProgress,
15	      actionContentSelector,
16	      actionContentOffsetY,
17	      actionContentDuration,
18	      onCoverComplete,
19	      onTransitionComplete,
20	    } = options;
21	
22	    await transitionRuntime.play(
23	      {
24	        veil,
25	        steps,
26	        onStepComplete: async (stepIndex) => {
27	          if (stepIndex !== 0) return;
28	          await onCoverComplete?.();
29	          await this._fadeActionContent(
30	            gsap,
31	            actionContentSelector,
32	            actionContentOffsetY,
33	            actionContentDuration,
34	          );
35	        },
36	        initialState: {
37	          active: true,
38	          progress: steps[0]?.from ?? 0,
39	        },
40	        finalState: {
41	          active: false,
42	          progress: inactiveProgress,
43	        },
44	      },
45	      gsap,
46	    );
47	    onTransitionComplete?.();
48	  }
49	
50	  setHeroTextVisible(visible: boolean): void {
51	    const textItems = this._getHeroTextItems();
52	    if (textItems.length === 0) return;
53	    if (visible) {
54	      TextReveal.setVisibleOn(textItems);
55	      return;
56	    }
57	    TextReveal.setVisibleOff(textItems);
58	  }
59	
60	  async playHeroTextRise(): Promise<void> {
61	    const textItems = this._getHeroTextItems();
62	    if (textItems.length === 0) return;
63	    TextReveal.setVisibleOff(textItems);
64	    await new Promise<void>((resolve) => {
65	      let completedCount = 0;
66	      textItems.forEach((item, index) => {
67	        window.setTimeout(() => {
68	          TextReveal.riseUp(item);
69	          completedCount += 1;
70	          if (completedCount !== textItems.length) return;
71	          resolve();
72	        }, index * HERO_TEXT_RISE_STAGGER_MS);
73	      });
74	    });
75	  }
